SELECT



    b.is_deleted = 0

        AND (p.product_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR p.product_code LIKE CONCAT('%', #{q.keyword}, '%'))


        AND b.user_id = #{q.userId}



        AND b.browse_time >= #{q.beginTime}


        AND b.browse_time <= #{q.endTime}


ORDER BY b.browse_time DESC, b.id DESC

SELECT COUNT(*)
FROM shop_consumer_browse
WHERE user_id = #{userId}
AND product_id = #{productId}

    AND id != #{excludeId}
